insert into public.products (id, group_key, name, full_name, model, price, orig_price, pct, origin, warranty_months,
  in_stock, image_url, key_figure, power, capacity, specs, description, points) values
('DK-042', 'may-loc-nuoc', 'Máy lọc nước BR653BY0', 'Máy lọc nước Tefal BR653BY0', 'BR653BY0', 15552000, 17010000, 9, 'Trung Quốc', 36, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-042.jpg', '{"v":"5","u":"L","l":"Dung tích"}'::jsonb, '2.200', '5', '[["Điện áp","220V / 50Hz"],["Công suất","2.200 W"],["Kích thước (R × S × C)","210 × 460 × 430 mm"],["Dung tích","5 lít"],["Loại","Máy lọc nước để bàn"],["Bảo hành","36 tháng"],["Xuất xứ","Trung Quốc"]]'::jsonb, 'Máy lọc nước BR653BY0 là mẫu máy lọc nước để bàn đa năng, tích hợp cả khả năng lọc sạch chuẩn RO lẫn ba chế độ nước nóng – lạnh – nguội trong một thiết bị duy nhất.', '["Tích hợp lọc RO 5in1 + đèn UV diệt khuẩn nguồn nước sau lọc","Thiết kế nhỏ gọn (210 x 460 x 430 mm) phù hợp gia đình đông thành viên, văn phòng nhỏ"]'::jsonb),
('DK-043', 'ngoai-bep', 'Máy hút bụi lau sàn không dây X-Clean 7 GF5736F4', 'Máy hút bụi lau sàn không dây Tefal X-Clean 7 GF5736F4', 'GF5736F4', 11145000, 13660000, 18, 'Pháp', 24, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-043.jpg', '{"v":"250","u":"W","l":"Công suất"}'::jsonb, '250', '0,7', '[["Công suất","250 W"],["Kích thước (R × S × C)","300 × 325 × 1192 mm"],["Dung tích","0,7 lít"],["Bảo hành","24 tháng"],["Xuất xứ","Pháp"]]'::jsonb, 'Tefal GF5736F4 là sản phẩm gia dụng thuộc thương hiệu Tefal, xuất xứ Pháp.', '["Kèm đế sạc kiêm chức năng làm sạch và sấy khô bằng khí nóng tới 60°C","Bao gồm phụ kiện vệ sinh: bàn chải, con lăn mềm, tấm lọc dự phòng","Lược kim loại chống rối tóc tích hợp"]'::jsonb),
('DK-044', 'ngoai-bep', 'Bàn ủi hơi nước IXEO QT2028F0', 'Bàn ủi hơi nước Tefal IXEO QT2028F0', 'QT2028F0', 10605000, 12999000, 18, 'Pháp', 24, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-044.jpg', '{"v":"2.170","u":"W","l":"Công suất"}'::jsonb, '2.170', '1,1', '[["Chất liệu","Nhựa"],["Công suất","2.170 W"],["Dung tích","1,1 lít"],["Loại","Steam ironing system 3 in 1"],["Bảo hành","24 tháng"],["Xuất xứ","Pháp"]]'::jsonb, 'Tefal QT2028F0 là bàn ủi hơi nước dạng bàn ủi kèm nồi hơi của thương hiệu Tefal, xuất xứ Pháp, dành cho gia đình có lượng quần áo cần ủi nhiều và muốn rút ngắn thời gian mỗi lần ủi.', '["Dung tích bình chứa 1.1 lít, thuận tiện tháo rời để châm nước giữa buổi ủi","Tính năng Vertical Steam, Self-Clean, Anti-drip system tối ưu cho việc ủi quần áo","Áp suất hơi tối đa 5.8 bar và lượng hơi 100 g/phút xuyên qua vải dày dễ dàng"]'::jsonb),
('DK-045', 'ngoai-bep', 'Bàn ủi hơi nước IXEO Power QT2020E0', 'Bàn ủi hơi nước Tefal IXEO Power QT2020E0', 'QT2020E0', 9412000, 11539000, 18, 'Trung Quốc', 12, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-045.jpg', '{"v":"2.170","u":"W","l":"Công suất"}'::jsonb, '2.170', '1,1', '[["Chất liệu","Ceramic"],["Công suất","2.170 W"],["Kích thước (R × S × C)","272 × 395 × 1140 mm"],["Dung tích","1,1 lít"],["Loại","Bàn ủi hơi nước đứng"],["Lượng hơi","90 g/phút"],["Bảo hành","12 tháng"],["Xuất xứ","Trung Quốc"]]'::jsonb, 'Bàn ủi hơi nước đứng IXEO Power QT2020E0 là giải pháp chăm sóc quần áo toàn diện, kết hợp bàn ủi hơi nước áp suất cao với cầu ủi thông minh tích hợp sẵn.', '["Dung tích 1.1 lít phù hợp cho nhu cầu ủi hơi nước liên tục trong thời gian dài","Tự ngắt khi quá nhiệt, đảm bảo an toàn trong quá trình sử dụng","Thiết kế dạng đứng cho phép thao tác thoải mái, không phải cúi người"]'::jsonb),
('DK-046', 'may-loc-nuoc', 'Máy lọc nước để bàn nóng-nguội BR453AY0', 'Máy lọc nước để bàn nóng-nguội Tefal BR453AY0', 'BR453AY0', 8720000, 9010000, 3, 'Pháp', null, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-046.jpg', '{"v":"5","u":"L","l":"Dung tích"}'::jsonb, '2.200', '5', '[["Công suất","2.200 W"],["Kiểu điều khiển","Cảm ứng"],["Kích thước (R × S × C)","195 × 376 × 362 mm"],["Dung tích","5 lít"],["Loại","Máy lọc nước để bàn"],["Công nghệ lọc (RO/Nano/UF)","Thẩm thấu ngược RO"],["Xuất xứ","Pháp"]]'::jsonb, 'Máy lọc nước để bàn Pure Water Compact BR453AY0 là thiết bị lọc nước thông minh dành cho gia đình, văn phòng và căn hộ có diện tích hạn chế.', '["Loại bỏ 97 chất độc hại (clo, mùi, màu, hạt siêu nhỏ, virus, vi khuẩn, hóa chất, kim loại nặng)","Diệt 99.9999% vi khuẩn và virus nhờ công nghệ lọc tiên tiến","Dung tích 5 lít phù hợp không gian hạn chế"]'::jsonb),
('DK-047', 'ngoai-bep', 'Máy hút bụi lau sàn không dây X-Combo GF3039KO', 'Máy hút bụi lau sàn không dây Tefal X-Combo GF3039KO', 'GF3039KO', 9936000, 11010000, 10, 'Trung Quốc', null, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-047.jpg', '{"v":"215","u":"W","l":"Công suất"}'::jsonb, '215', '0,6', '[["Công suất","215 W"],["Kích thước (R × S × C)","270 × 180 × 1142 mm"],["Dung tích","0,6 lít"],["Loại","Máy hút bụi không dây"],["Xuất xứ","Trung Quốc"]]'::jsonb, 'Máy hút bụi lau nhà X-Combo GF3039KO là thiết bị vệ sinh không dây hai trong một, cho phép hút bụi và lau sàn cùng lúc trong một lần di chuyển.', '["Hút bụi và lau sàn 2 trong 1 nhờ công nghệ Aerospin, tiết kiệm thời gian dọn dẹp","Pin 1950mAh cho thời gian dùng liên tục ~60 phút, phù hợp căn hộ nhỏ","Thiết kế tự đứng gọn nhẹ (3.6 kg) dễ cất giữ và sử dụng"]'::jsonb),
('DK-048', 'ngoai-bep', 'Máy hút bụi không dây X-Force Flex 13.6 TY9AD2WO', 'Máy hút bụi không dây Tefal X-Force Flex 13.6 TY9AD2WO', 'TY9AD2WO', 10660000, 11010000, 3, 'Pháp', 36, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-048.jpg', '{"v":"300","u":"W","l":"Công suất"}'::jsonb, '300', '0,7', '[["Công suất","300 W"],["Kiểu điều khiển","Phím bấm"],["Kích thước (R × S × C)","408 × 804 × 178 mm"],["Dung tích","0,7 lít"],["Loại","Máy hút bụi cầm tay không dây/máy hút bụi lau sàn"],["Thời lượng pin","60 phút"],["Bảo hành","36 tháng"],["Xuất xứ","Pháp"]]'::jsonb, 'Máy hút bụi không dây X-Force Flex 13.60 TY9AD2WO là dòng máy hút bụi cầm tay cao cấp, mang đến hiệu năng làm sạch mạnh mẽ trong một thiết kế mỏng nhẹ, linh hoạt.', '["Công suất hút 150 Air Watts xử lý bụi mịn, lông thú cưng hiệu quả","Thiết kế mỏng nhẹ (5.4 kg) với ống Flex linh hoạt","Pin tháo rời, công nghệ Aerospin hỗ trợ làm sạch sâu"]'::jsonb),
('DK-049', 'may-xay-ep', 'Máy xay sinh tố làm sữa hạt BL985A31', 'Máy xay sinh tố làm sữa hạt Tefal BL985A31', 'BL985A31', 5915000, 7259000, 19, 'Trung Quốc', 24, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-049.jpg', '{"v":"1.300","u":"W","l":"Công suất"}'::jsonb, '1.300', '1,4', '[["Chất liệu","Thủy tinh"],["Điện áp","220V / 50Hz"],["Công suất","1.300 W"],["Kiểu điều khiển","Phím bấm"],["Dung tích","1,4 lít"],["Bảo hành","24 tháng"],["Xuất xứ","Trung Quốc"]]'::jsonb, 'Máy xay đa năng BL985A31 là thiết bị nhà bếp cao cấp kết hợp giữa khả năng xay và nấu, giúp bạn chế biến từ sinh tố, sữa hạt cho tới súp nóng, cháo dinh dưỡng chỉ với một chiếc máy.', '["Công suất 1300W đủ mạnh xử lý nguyên liệu cứng như đá viên, hạt ngũ cốc","Công nghệ Nutrikeep độc quyền giữ nguyên dinh dưỡng trong quá trình chế biến","Dung tích 1.4 lít phù hợp chế biến lượng vừa cho gia đình"]'::jsonb),
('DK-050', 'may-xay-ep', 'Máy xay sinh tố làm sữa hạt UltraBlend Silence BL98SC66', 'Máy xay sinh tố làm sữa hạt Tefal UltraBlend Silence BL98SC66', 'BL98SC66', 5709000, 7259000, 21, 'Trung Quốc', 24, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-050.jpg', '{"v":"2.000","u":"W","l":"Công suất"}'::jsonb, '2.000', '2', '[["Chất liệu","Thủy tinh"],["Điện áp","220V / 50Hz"],["Công suất","2.000 W"],["Kiểu điều khiển","Cảm ứng"],["Kích thước (R × S × C)","573 × 354 × 327 mm"],["Dung tích","2 lít"],["Loại","Máy xay sữa hạt"],["Bảo hành","24 tháng"],["Xuất xứ","Trung Quốc"]]'::jsonb, 'Máy xay nấu đa năng BL98SC66 là mẫu máy làm sữa hạt cao cấp dành cho gian bếp hiện đại, đáp ứng đa dạng nhu cầu chế biến từ sữa hạt, sinh tố, súp cho đến cháo dinh dưỡng.', '["Tự ngắt khi quá tải và chỉ hoạt động khi lắp khớp cối với thân máy, đảm bảo an toàn"]'::jsonb),
('DK-051', 'ngoai-bep', 'Bàn ủi hơi nước đứng IXEO Vision QT1811E0', 'Bàn ủi hơi nước đứng Tefal IXEO Vision QT1811E0', 'QT1811E0', 5567000, 7239000, 23, 'Trung Quốc', 12, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-051.jpg', '{"v":"2.400","u":"W","l":"Công suất"}'::jsonb, '2.400', '1,2', '[["Chất liệu","Ceramic"],["Công suất","2.400 W"],["Dung tích","1,2 lít"],["Loại","Hơi nước"],["Lượng hơi","80 g/phút"],["Bảo hành","12 tháng"],["Xuất xứ","Trung Quốc"]]'::jsonb, 'Bàn ủi hơi nước đứng IXEO Vision QT1811E0 là giải pháp chăm sóc quần áo toàn diện dành cho gia đình hiện đại, giúp trang phục luôn phẳng mượt, sạch khuẩn và giữ được phom dáng.', '["Mặt đế kim loại phủ Ceramic, bền bỉ và dễ trượt trên vải","Công nghệ Smart Protect hạn chế cháy vải, tăng độ an toàn khi sử dụng","Dung tích 1.2 lít, phù hợp cho gia đình bận rộn cần ủi nhiều quần áo"]'::jsonb),
('DK-052', 'dao-dung-cu', 'Bộ dao EverSharp Pro K2977S44', 'Bộ dao Tefal EverSharp Pro K2977S44', 'K2977S44', 4289000, 5269000, 19, 'Pháp', 36, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-052.jpg', '{"v":"6","u":"món","l":"Trong bộ"}'::jsonb, null, null, '[["Chất liệu","Inox"],["Chất liệu thép","thép Đức"],["Bảo hành","36 tháng"],["Xuất xứ","Pháp"]]'::jsonb, 'Bộ dao kéo 6 món Ever Sharp K2977S44 là bộ dụng cụ cắt thái cao cấp dành cho căn bếp gia đình, nổi bật với khả năng tự mài sắc tích hợp ngay trong hộp đựng.', '["Lưỡi dao thép Đức cao cấp kết hợp hộp tự mài Ever Sharp duy trì độ sắc bén lâu dài","Thân inox đúc nguyên khối sang trọng, thiết kế hộp dao đứng tiện lợi","Bộ 6 món dao đa dạng kích thước: 9, 12, 16.5, 20, 20 cm"]'::jsonb),
('DK-053', 'dao-dung-cu', 'Bộ dao EverSharp Pro K297S744', 'Bộ dao Tefal EverSharp Pro K297S744', 'K297S744', 3856000, 4739000, 19, 'Pháp', 24, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-053.jpg', '{"v":"6","u":"món","l":"Trong bộ"}'::jsonb, null, null, '[["Chất liệu","Inox"],["Bảo hành","24 tháng"],["Xuất xứ","Pháp"]]'::jsonb, 'Bộ dao kéo 6 món Ever Sharp K297S744 là bộ dụng cụ nhà bếp hỗ trợ sơ chế thực phẩm chính xác, gọn gàng và an toàn hơn trong căn bếp gia đình.', '["Bộ dao 6 món tích hợp dụng cụ tự mài Ever Sharp, luôn sắc bén không cần mài thủ công","Lưỡi thép không gỉ Đức và tay cầm ergonomic tăng độ bền và thoải mái khi sử dụng","Hệ thống chắn ngón tay và khóa dao trong khối gỗ khi mài đảm bảo an toàn"]'::jsonb),
('DK-054', 'ngoai-bep', 'Máy hút bụi không dây X-Force Flex 9.60 TY2039WO', 'Máy hút bụi không dây Tefal X-Force Flex 9.60 TY2039WO', 'TY2039WO', 5956000, 6600000, 10, 'Pháp', 36, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-054.jpg', '{"v":"250","u":"W","l":"Công suất"}'::jsonb, '250', '0,4', '[["Công suất","250 W"],["Kiểu điều khiển","Phím bấm"],["Kích thước (R × S × C)","780 × 304 × 130 mm"],["Dung tích","0,4 lít"],["Loại","Máy hút bụi không dây"],["Thời lượng pin","45 phút"],["Bảo hành","36 tháng"],["Xuất xứ","Pháp"]]'::jsonb, 'Máy hút bụi không dây X-Force Flex 9.60 TY2039WO là thiết bị làm sạch hiện đại dành cho gia đình, kết hợp giữa lực hút mạnh, thiết kế nhẹ nhàng và khả năng vận hành thông minh.', '["Làm sạch thông minh với khả năng tự động điều chỉnh công suất hút theo loại sàn","Đèn LED báo hiệu nguồn và thiết kế ống linh hoạt giúp hút bụi mọi nơi không cần cúi xuống","Màn hình điều khiển thông minh hiển thị thời gian chạy còn lại và cảnh báo vệ sinh"]'::jsonb),
('DK-055', 'noi-ap-suat', 'Nồi áp suất điện đa năng Smart Pro IH CY638868', 'Nồi áp suất điện đa năng Tefal Smart Pro IH CY638868', 'CY638868', 3914000, 4810000, 19, 'Pháp', 24, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-055.jpg', '{"v":"5","u":"L","l":"Dung tích"}'::jsonb, '1.300', '5', '[["Chất liệu","Inox"],["Công suất","1.300 W"],["Kích thước (R × S × C)","428 × 333 × 486 mm"],["Dung tích","5 lít"],["Bảo hành","24 tháng"],["Xuất xứ","Pháp"]]'::jsonb, 'Nồi áp suất điện EPC Smart Pro IH Multicooker CY638868 là thiết bị nấu đa năng dành cho gian bếp gia đình, kết hợp giữa nguyên lý nấu áp suất và khả năng chế biến hàng loạt món ăn khác nhau chỉ …', '["Lòng nồi inox 3 lớp dày 1.8mm và nhôm chống dính bền bỉ","Hẹn giờ 24h và màn hình LED tiện lợi cho việc theo dõi","Van xả áp tự động và khóa an toàn ngăn mở nắp khi còn áp suất"]'::jsonb),
('DK-056', 'dao-dung-cu', 'Bộ dao EverSharp Pro K297S644', 'Bộ dao Tefal EverSharp Pro K297S644', 'K297S644', 3513000, 4319000, 19, 'Trung Quốc', 24, true, 'https://krtjhvqbdjbjibamgslg.supabase.co/storage/v1/object/public/bnb-product-images/manual-thumb/DK-056.jpg', '{"v":"5","u":"món","l":"Trong bộ"}'::jsonb, null, null, '[["Chất liệu","Inox"],["Chất liệu thép","thép Đức"],["Bảo hành","24 tháng"],["Xuất xứ","Trung Quốc"]]'::jsonb, 'Bộ dao 5 món Ever Sharp K297S644 là bộ dao nhà bếp tích hợp dụng cụ mài chuyên dụng, được thiết kế để giữ cho lưỡi dao luôn sắc bén mà người dùng gần như không phải bận tâm đến việc bảo dưỡng.', '["Bộ 5 món kích thước đa dạng (9, 12, 16.5, 20, 20 cm) phục vụ nhiều nhu cầu sơ chế","Chất liệu thép không gỉ Đức chất lượng cao đảm bảo độ bền cao cho gia đình nấu ăn thường xuyên"]'::jsonb),
